import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import '../index.css';

const JobSeekerForm = () => {
  const [formData, setFormData] = useState({
    full_name: '',
    email: '',
    phone_number: '',
    gender: '',
    country: '',
    city: '',
    degree: '',
    graduation_year: '',
    university: '',
    skills: '',
    expected_salary: '',
    age: '',
  });

  const navigate = useNavigate();

  const handleChange = (e) => 
    setFormData({ ...formData, [e.target.name]: e.target.value });

  const handleSubmit = (e) => {
    e.preventDefault();

    const cu = JSON.parse(localStorage.getItem("currentUser") || "null") || {};
    const email = cu.email || formData.email || "";

    const profileToSave = { ...formData, email, id: Date.now() };

    const existing = JSON.parse(localStorage.getItem("jobSeekerProfiles") || "[]");
    existing.push(profileToSave);
    localStorage.setItem("jobSeekerProfiles", JSON.stringify(existing));

    localStorage.setItem("profileCreated", "true");
    const updatedUser = { ...cu, role: "jobseeker", email };
    localStorage.setItem("currentUser", JSON.stringify(updatedUser));

    alert("Job Seeker profile created!");
    navigate("/dashboard");
  };

  return (
    <div className="form-container">
      <h1 className="heading">SoftScale</h1>
      <div className="form-box">
        <h2>Job Seeker Profile</h2>

        {/* Only Permanent Job type now */}
        <div className="toggle-group">
          <label>
            <input
              type="radio"
              name="jobType"
              value="permanent"
              checked
              readOnly
            />
            Permanent Job
          </label>
        </div>

        <form onSubmit={handleSubmit}>
          <input name="full_name" placeholder="Full Name" onChange={handleChange} required />
          <input name="email" type="email" placeholder="Email" onChange={handleChange} required />
          <input name="phone_number" placeholder="Phone Number" onChange={handleChange} required />
          <input name="country" placeholder="Country" onChange={handleChange} />
          <input name="city" placeholder="City" onChange={handleChange} />
          <input name="degree" placeholder="Degree" onChange={handleChange} />
          <input name="skills" placeholder="Skills" onChange={handleChange} />

          {/* Permanent job fields */}
          <input name="expected_salary" placeholder="Expected Salary" onChange={handleChange} />
          <input name="university" placeholder="University" onChange={handleChange} />
          <input name="graduation_year" placeholder="Graduation Year" onChange={handleChange} />

          <button type="submit" className="btn-primary">Submit</button>
        </form>
      </div>
    </div>
  );
};

export default JobSeekerForm;
